import { HelmApp } from "#components/helm-app.js";
import { lazy } from "#utils/lazy.js";

/**
 * kubernetes-replicator copies secrets between namespaces
 * (e.g. the connection strings generated by the MongoDB operator).
 */
export const replicator = lazy(
  () =>
    new HelmApp("replicator", {
      // PHASE0: confirm the namespace of the live release (deploy.sh installs it in "default")
      namespace: "default",
      releaseName: "kubernetes-replicator",
      chart: "kubernetes-replicator",
      repo: "https://helm.mittwald.de",
    }),
);
